sketches.source:
setcpm(128/4)

// Seven bars of build. Bar eight is the drop. The drop is a sad trombone
const build = "<1 1 1 1 1 1 1 0>"

// The snare roll gets faster and faster, as if this is going somewhere
roll: s("<sd*2 sd*4 sd*4 sd*8 sd*8 sd*16 sd*32 ~>").gain(saw.range(.15, .5)).hpf(400).room(.3)

// The riser climbs for seven bars
riser: s("white").mask(build).hpf(saw.range(300, 9000).slow(8)).gain(saw.range(.02, .1).slow(8))

// Plucks whose filter opens wider and wider
plucks: n("0 2 4 7 4 2 0 4").scale("F:minor").transpose(12).mask(build)
  .s("square").pw(.3).lpf(saw.range(400, 6000).slow(8)).decay(.1).sustain(0)
  .delay(.3).delaytime(3/16).gain(.18)

// The hype man asks the obvious question in bar seven
hype: note("<~ ~ ~ ~ ~ ~ [f4 f4 ab4 c5] ~>").s("voice").syl("ar yoo re dee").voicetype("tenor")
  .mono(1).vglide(.04).attack(.02).release(.3).room(.4).gain(.3)

// And here it is: the drop
trombone: note("<~ ~ ~ ~ ~ ~ ~ [g3 gb3 f3 e3@4]>").s("sawtooth").timbre("reed").vowel("oo")
  .mono(1).glide(.12).vib(5).vibdepth(.3).lpf(1400)
  .attack(.03).sustain(.8).release(.6).gain(.22)

// Then it starts building again. It will always start building again

setcpm(120/4)

// The patch: a saw pushed into a tube curve and out of a combo cabinet
const overdrive = (x) => x.s("sawtooth").curve("tube").drive(14).bias(.1)
  .attack(.003).decay(.3).sustain(.5).release(.1).lpf(3400).cab("combo").room(.25)

// The band vamps on E minor and A, politely, then fades out over bars 9 to 16 and goes home
drums: s("bd ~ sd ~ bd bd sd ~, hh*8").gain(.45).fadeout(8, 8)
bass: note("<e2 e2 a1 a1>").struct("x ~ x x ~ x x ~").s("sawtooth").lpf(600)
  .decay(.2).sustain(.4).release(.1).gain(.4).fadeout(8, 8)
rhythm: note("<[e3,b3,e4] [e3,b3,e4] [a2,e3,a3] [a2,e3,a3]>").struct("x ~ ~ x ~ ~ x ~")
  .overdrive().gain(.14).fadeout(8, 8)

// The solo: seeded noodling with ratchets, and a whammy-bar dive at the end of every fourth bar
// It does not notice that the band has left
solo: n(irand(12).segment(16)).scale("E:minor pentatonic").transpose(12)
  .sometimesBy(.3, x => x.ply(2)).lastOf(4, x => x.penv(-12).pdecay(.4))
  .mono(1).glide(.02).overdrive().seed("noodle").gain(.18)

// The audience claps politely at first, and leaves with the band
crowd: s("crowd").slow(4).intensity(.3).gain(.1).fadeout(8, 8)

setcpm(72/4)

// A love song, written with a rhyming dictionary that only has two pages
// Piano arpeggios through C, Am, F and G
piano: note("<[c3 g3 c4 e4 g4 e4 c4 g3] [a2 e3 a3 c4 e4 c4 a3 e3] [f2 c3 f3 a3 c4 a3 f3 c3] [g2 d3 g3 b3 d4 b3 g3 d3]>")
  .s("triangle").timbre("soft").attack(.005).decay(.8).sustain(.1).release(.9).room(.5).gain(.26)

// Every word rhymes with moon, or with heart: there are no other feelings
// The syllables carry the same weights as the notes
crooner: note("<[e4@3 g4 c5@4] [c5@2 b4@2 a4@4] [a4@3 g4 f4@2 e4@2] [d4@6 ~@2]>")
  .s("voice").syl("<[moon@3 yoon spoon@4] [toon@2 kroon@2 soon@4] [hart@3 part star@2 far@2] [oo@6 ~@2]>")
  .voicetype("tenor").mono(1).vglide(.12)
  .attack(.1).release(1).space("hall").gain(.3)

// The strings come in exactly when you knew they would
strings: note("<[e3,g3,c4] [e3,a3,c4] [f3,a3,c4] [g3,b3,d4]>").mask("<0 0 0 0 1 1 1 1>")
  .s("sawtooth").unison(4).detune(20).lpf(1800).attack(.8).sustain(.9).release(1.5).room(.6).gain(.12)
bass: note("<c2 a1 f1 g1>").s("sine").attack(.05).sustain(.8).release(.6).gain(.32)

setcpm(84/4)

// The patch: a reedy saw through an o vowel, with far too much vibrato and far too much glide
const sax = (x) => x.s("sawtooth").timbre("reed").vowel("o").mono(1).glide(.12)
  .vib(5).vibdepth(.4).attack(.05).sustain(.7).release(.4).lpf(2200).room(.5)

// Every phrase ends with an unnecessary run up the scale, to show that it can
lead: note("<[e5@3 d5 b4@4] [c5@2 d5@2 e5@4] [g5@3 e5 d5@2 b4@2] [a4 b4 c5 d5 e5 g5 a5 b5]>")
  .sax().gain(.22)

// Rhodes chords so major-seventh they are basically lying down: Cmaj9, Am9, Fmaj9, G13
keys: note("<[e3,g3,b3,d4] [c3,e3,g3,b3] [a3,c4,e4,g4] [f3,a3,b3,e4]>").struct("x ~ ~ [~ x] ~ ~ x ~")
  .s("sine").fm(1.1).fmh(2).trem(4).tremdepth(.25)
  .decay(1).sustain(.3).release(.8).lpf(2400).room(.4).gain(.24)

// A fretless bass that slides into every note, and a snare drowning in reverb
bass: note("<[c2@3 g1] [a1@3 e2] [f1@3 c2] [g1@3 d2]>").s("sine").mono(2).glide(.1).shape(.1)
  .decay(.6).sustain(.4).release(.3).gain(.4)
drums: s("bd ~ ~ bd, ~ sd ~ sd, [~ hh]*4").room(.7).size(.9).gain(.32)

// A wind chime on every downbeat, for no reason at all
chime: n(irand(8).segment(1)).scale("C:major pentatonic").transpose(24)
  .s("sine").fm(3).fmh(2.76).decay(2).sustain(0).release(2)
  .pan(rand).seed("chime").room(.6).gain(.08)

setcpm(140/4)

// The song plays for four bars, then ends. Then ends again. Then ends again. Then actually ends
// form: A is the song, B the big held chord, C one more bar because the crowd is still there
// .once() plays the layout a single time, and then there is finally silence
const song = note("<[e3,b3,e4] [e3,b3,e4] [g3,d4,g4] [a3,e4,a4]>").struct("x ~ x x ~ x x ~")
const held = note("[e3,b3,e4,g#4]").slow(4)
const burst = note("[e3,b3,e4]*8")

guitar: form("A@4 B@2 C B@2 C B@2 C B@4", song, held, burst).once()
  .s("sawtooth").curve("tube").drive(14).attack(.003).decay(.4).sustain(.6).release(.6)
  .lpf(3200).cab("stack").room(.3).gain(.16)
bass: form("A@4 B@2 C B@2 C B@2 C B@4", note("<e1 e1 g1 a1>").struct("x*8"), note("e1").slow(4), note("e1*8")).once()
  .s("sawtooth").lpf(500).decay(.3).sustain(.6).release(.5).gain(.36)

// The drummer rolls into a crash on every ending, and believes every one of them
drums: form("A@4 B@2 C B@2 C B@2 C B@4",
  s("bd ~ sd ~ bd bd sd ~, hh*8"),
  s("[cr,bd] ~ ~ ~, [lt mt ht lt mt ht ht ht]*2"),
  s("bd sd bd sd, hh*8")).once().gain(.45)

// The house cheers, at last, and the applause dies away
applause: s("crowd").slow(4).intensity(.8).gain(.22).enter(13).exit(22).fadeout(4, 18)
claps: s("cp*16?0.5").seed("encore").pan(rand).gain(rand.range(.08, .2)).enter(13).exit(22).fadeout(4, 18)
